def run(ctx, args):
    import math

    patterns = {
        "pattern_hexagonal_3layer": "3 staggered rows with offset r",
        "pattern_corner_anchor_4": "4 large corner circles + center cluster",
        "pattern_diagonal_bands": "2 diagonal bands of varying radii",
        "pattern_concentric_hexagons": "Central circle with 2 hexagonal shells"
    }

    if args.get("action") == "list_patterns":
        return {"patterns": patterns}

    if args.get("action") == "get_coordinates":
        n = args.get("n", 26)
        pattern = args.get("pattern", "pattern_corner_anchor_4")

        if pattern == "pattern_corner_anchor_4":
            # 4 corners + 5 medium + 6 small + 5 tiny + 6 gap fillers = 26
            centers = []
            # 4 large corner circles
            for sx, sy in [(0.2, 0.2), (0.8, 0.2), (0.2, 0.8), (0.8, 0.8)]:
                centers.append([sx, sy])
            # 5 medium in central cross
            for i, x in enumerate([0.4, 0.5, 0.6, 0.35, 0.65]):
                centers.append([x, 0.5])
            # 6 small in quadrants
            for i, (qx, qy) in enumerate([(0.4, 0.4), (0.6, 0.4), (0.4, 0.6), (0.6, 0.6),
                                          (0.45, 0.45), (0.55, 0.55)]):
                centers.append([qx, qy])
            # Fill remaining with gap optimizers
            for i, (gx, gy) in enumerate([(0.3, 0.3), (0.7, 0.3), (0.3, 0.7), (0.7, 0.7),
                                          (0.42, 0.58), (0.58, 0.42)]):
                centers.append([gx, gy])

        elif pattern == "pattern_hexagonal_3layer":
            # 3 layers of hexagonal packing
            layer0 = [(0.33, 0.2), (0.5, 0.2), (0.67, 0.2)]
            layer1 = [(0.25, 0.433), (0.5, 0.433), (0.75, 0.433)]
            layer2 = [(0.33, 0.666), (0.5, 0.666), (0.67, 0.666)]
            layer3 = [(0.25, 0.9)]
            centers = layer0 + layer1 + layer2 + layer3

        else:
            centers = [[0.5, 0.5]]

        return {"centers": centers, "count": len(centers)}

    return {"message": "Use list_patterns or get_coordinates action"}

